def rotar(lista, k):
    if not lista:
        return []

    n = len(lista)
    k %= n

    if k == 0:
        return lista[:]

    return lista[-k:] + lista[:-k]

def romano(n):
    if not isinstance(n, int) or isinstance(n, bool) or not 1 <= n <= 3999:
        raise ValueError("El número debe estar entre 1 y 3999")

    valores = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    resultado = []
    for valor, simbolo in valores:
        while n >= valor:
            resultado.append(simbolo)
            n -= valor

    return "".join(resultado)

def anagramas(a, b):
    a = a.replace(" ", "").lower()
    b = b.replace(" ", "").lower()
    return sorted(a) == sorted(b)

def balanceado(s):
    pila = []
    cierre = {')': '(', ']': '[', '}': '{'}

    for c in s:
        if c in '([{':
            pila.append(c)
        elif c in ')]}':
            if not pila or pila[-1] != cierre[c]:
                return False
            pila.pop()

    return not pila
